function showAnalysisResults(data){const root=$('analysis-results');root.replaceChildren();const head=document.createElement('p');head.textContent=data.solverName+' '+data.solverVersion+' · '+data.designCode+' · '+data.analysisDate;root.append(head);for(const row of data.memberResults){const item=document.createElement('div');item.className='life-row';const b=document.createElement('b');b.textContent=(design.elements.find(e=>e.id===row.memberId)?.label||row.memberId)+' · '+row.status;const small=document.createElement('small');small.textContent='Utilisation: '+(row.utilization===null?'Not supplied':row.utilization)+' · Combination: '+row.governingCombination+(row.notes?' · '+row.notes:'');item.append(b,small);root.append(item)}const notice=document.createElement('p');notice.className='studio-note';notice.textContent=data.notice;root.append(notice)}
$('analysis-export').onclick=()=>{ensureGovernance(design);const analytical=design.analysis?.model||buildAnalyticalModel(design);const legacy=buildAnalysisPackage(design,{projectName:design.title,units:design.units||'m',designCode:$('analysis-code').value||'UNSPECIFIED'});const pkg={projectModel:{id:design.id,title:design.title,revision:design.revision,approvals:design.approvals},analyticalModel:analytical,solverExchange:legacy,notice:'Geometry and analytical idealisation package only. No structural analysis has been run.'};download('conflow-analytical-solver-package.json',JSON.stringify(pkg,null,2),'application/json')};
$('analysis-results-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());importedAnalysis=validateSolverResults(raw,design);showAnalysisResults(importedAnalysis)}catch(err){$('analysis-results').textContent='Results import rejected: '+err.message}finally{e.target.value=''}};
function renderWorkflowStatus(){const root=$('workflow-status');if(!root)return;root.replaceChildren();ensureGovernance(design);for(const [key,a] of Object.entries(design.approvals)){const row=document.createElement('div');row.className='life-row';const b=document.createElement('b');b.textContent=({technical:'Technical CAD',presentation:'Presentation Studio',engineering:'Structural engineering',quantitySurveying:'BOQ / Quantity surveying'})[key]+' · '+a.status;const small=document.createElement('small');small.textContent=a.approver?(a.approver+' · '+a.role+' · revision '+a.revision):'Not approved · current model revision '+design.revision.number;row.append(b,small);root.append(row)}const rev=document.createElement('p');rev.className='studio-note';rev.textContent='Controlled model revision '+design.revision.number+' · '+design.elements.length+' CAD objects';root.append(rev)}
document.querySelectorAll('[data-approve]').forEach(btn=>btn.onclick=async()=>{try{recordApproval(design,btn.dataset.approve,{approver:$('workflow-approver').value,role:$('workflow-role').value,notes:$('workflow-notes').value});const saved=await window.desktop.saveDesign({id:design.id,title:design.title,version:design.version,model:design});design.version=saved.version;renderWorkflowStatus();$('cad-status').textContent=btn.dataset.approve+' approval recorded against revision '+design.revision.number}catch(err){$('cad-status').textContent='Approval not recorded: '+err.message}});
$('analysis-build').onclick=async()=>{ensureGovernance(design);const parseLines=id=>$(id).value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((label,i)=>({id:'LC'+(i+1),label}));design.analysis.designCode=$('analysis-code').value.trim()||null;design.analysis.loadCases=parseLines('analysis-load-cases');design.analysis.combinations=parseLines('analysis-combinations');design.analysis.model=buildAnalyticalModel(design);design.analysis.model.loadCases=design.analysis.loadCases;design.analysis.model.combinations=design.analysis.combinations;design.analysis.model.designCode=design.analysis.designCode;reviseModel(design,'Structural analytical inputs updated');design.version=(design.version||0)+1;const check=validateAnalyticalModel(design.analysis.model,design);const root=$('analysis-model-summary');root.replaceChildren();const head=document.createElement('p');head.textContent=design.analysis.model.nodes.length+' frame nodes · '+design.analysis.model.members.length+' structural members · '+(check.valid?'Ready for solver input':'Engineering input incomplete');root.append(head);for(const msg of [...design.analysis.model.warnings,...check.issues]){const line=document.createElement('small');line.textContent='• '+msg;root.append(line)}const saved=await window.desktop.saveDesign({id:design.id,title:design.title,version:design.version,model:design});design.version=saved.version;renderWorkflowStatus();$('cad-status').textContent='Analytical model saved at project revision '+design.revision.number+' · no analysis run'};
const renderQueue=[];
$('offline-render-export').onclick=async()=>{try{ensureGovernance(design);const job=createOfflineRenderJob(design,{name:$('render-job-name').value||'Presentation render',camera:{position:viewport?.camera.position.toArray()||[],target:viewport?.controls.target.toArray()||[]},settings:{quality:$('render-quality').value,lighting:$('render-lighting').value,weather:$('render-weather').value,exposure:+$('render-exposure').value,sunAzimuth:+$('sun-azimuth').value,sunElevation:+$('sun-elevation').value,reflection:+$('render-reflection').value},backend:'offline-pathtracer'});design.presentation.jobs=[...(design.presentation.jobs||[]),{jobId:job.jobId,sourceRevision:job.sourceRevision,name:job.name,status:job.status,backend:job.backend}];const saved=await window.desktop.saveDesign({id:design.id,title:design.title,version:design.version,model:design});design.version=saved.version;download('conflow-offline-render-job.json',JSON.stringify(job,null,2),'application/json');$('render-queue-status').textContent='Offline render manifest exported for project revision '+job.sourceRevision+'. A compatible external renderer is required to execute it.'}catch(err){$('render-queue-status').textContent='Could not create offline render job: '+err.message}};

function drawRenderQueue(){const root=$('render-queue-list');root.replaceChildren();renderQueue.forEach((job,i)=>{const row=document.createElement('div');row.className='life-row';const name=document.createElement('b');name.textContent=(i+1)+'. '+job.name;const meta=document.createElement('small');meta.textContent=job.view+' · '+job.scale+'× · '+job.status;row.append(name,meta);root.append(row)})}
$('render-queue-add').onclick=()=>{if(!viewport)return;renderQueue.push({name:$('render-job-name').value.trim()||'Presentation '+(renderQueue.length+1),view,scale:+$('render-export-scale').value,position:viewport.camera.position.toArray(),target:viewport.controls.target.toArray(),status:'Queued'});drawRenderQueue();$('render-queue-status').textContent=renderQueue.length+' render job(s) queued.'};
$('render-queue-run').onclick=async()=>{if(!viewport||!renderQueue.length){$('render-queue-status').textContent='Add at least one view to the queue.';return}const button=$('render-queue-run');button.disabled=true;try{for(let i=0;i<renderQueue.length;i++){const job=renderQueue[i];job.status='Rendering';drawRenderQueue();$('render-queue-status').textContent='Rendering '+(i+1)+' of '+renderQueue.length+': '+job.name;viewport.camera.position.fromArray(job.position);viewport.controls.target.fromArray(job.target);viewport.camera.lookAt(viewport.controls.target);viewport.controls.update();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const a=document.createElement('a');a.href=viewport.capture(job.scale);a.download='conflow-'+job.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.png';a.click();job.status='Exported';drawRenderQueue();await new Promise(resolve=>setTimeout(resolve,250))}$('render-queue-status').textContent='Queue complete. '+renderQueue.length+' image(s) exported.'}catch(err){$('render-queue-status').textContent='Queue stopped: '+err.message}finally{button.disabled=false}};

$('texture-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return;const image=new Image(),url=URL.createObjectURL(file);image.onload=async()=>{try{const max=2048,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.92),name=$('texture-material').value,channel=$('texture-channel').value;design.renderAssets={...(design.renderAssets||{}),[name]:{...(design.renderAssets?.[name]||{}),[channel]:data}};reviseModel(design,'Presentation material map updated');design.version=(design.version||0)+1;viewport?.setMaterialMap(name,data,channel);const saved=await window.desktop.saveDesign({id:design.id,title:design.title,version:design.version,model:design});design.version=saved.version;renderWorkflowStatus();$('cad-status').textContent=channel+' map applied to '+name+' and saved with the project'}catch(err){console.error(err);$('cad-status').textContent='Texture import failed: '+err.message}finally{URL.revokeObjectURL(url)}};image.onerror=()=>{URL.revokeObjectURL(url);$('cad-status').textContent='Could not read texture image'};image.src=url};

