$('run-life-simulation').onclick=()=>{const x=simulateServiceLife(design.elements,{years:+$('life-years').value,occupancy:+$('life-occupancy').value,exposure:$('life-exposure').value,maintenance:+$('life-maintenance').value});const root=$('life-results');root.replaceChildren();const summary=document.createElement('p');summary.textContent=x.summary.elements+' components · '+x.summary.highAttention+' high-attention · '+x.summary.monitor+' monitor';root.append(summary);for(const row of x.rows){const item=document.createElement('div');item.className='life-row';const title=document.createElement('b');title.textContent=row.label+' · '+row.material;const detail=document.createElement('small');detail.textContent=row.tier+' · suggested inspection / maintenance review around year '+row.maintenanceYear+' · scenario index '+row.projectedDeterioration+'/100';item.append(title,detail);root.append(item)}const notice=document.createElement('p');notice.className='studio-note';notice.textContent=x.notice;root.append(notice)};
document.querySelectorAll('[data-tool-group]').forEach(b=>b.onclick=()=>{const p=$('group-'+b.dataset.toolGroup);p.classList.toggle('hidden');b.classList.toggle('expanded',!p.classList.contains('hidden'))});
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('active',x.dataset.tool===tool));$('active-tool-label').textContent=tool==='select'?'Selection':defaults[tool]?.label||tool;$('cad-status').textContent=tool==='select'?'Select an object':tool==='measure'?'Click to inspect coordinates':'Click the plan to place '+tool});
function addObject(x,y){const p=snapPoint(x,y,design.elements,.2,snap),e=make(tool,p.x,p.y,0);if(tool==='window')e.z=.9;if(tool==='door'||tool==='window')hostOpening(e,design.elements);const check=validateGeometry({...design,elements:[...design.elements,e]});if(!check.valid){$('cad-status').textContent='Placement rejected · '+check.errors.join(' · ');return}checkpoint();design.elements.push(e);selected=e.id;dirty('Placed '+e.type+' · geometry validated · hosted opening subtraction updates in 3D')}
function planPoint(ev){const svg=$('cad-canvas'),p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse());return{x:(q.x-450)/48+5,y:(q.y-285)/48+5}}
function hitPlan(x,y){return design.elements.slice().reverse().find(o=>{const dx=x-o.x,dy=y-o.y,ang=-(o.rotation||0)*Math.PI/180,l=dx*Math.cos(ang)-dy*Math.sin(ang),w=dx*Math.sin(ang)+dy*Math.cos(ang);return Math.abs(l)<=o.length/2+.08&&Math.abs(w)<=o.width/2+.08})}
$('cad-canvas').addEventListener('pointerdown',ev=>{if(tool!=='select'||ev.button!==0)return;const p=planPoint(ev),hit=hitPlan(p.x,p.y);if(!hit){if(!ev.shiftKey){selected=null;selectedIds.clear();renderCad()}return}if(ev.shiftKey){if(selectedIds.has(hit.id))selectedIds.delete(hit.id);else selectedIds.add(hit.id);selected=hit.id}else if(!selectedIds.has(hit.id)){selectedIds=new Set([hit.id]);selected=hit.id}if(!selectedIds.size)selected=null;renderCad();if(selectedIds.has(hit.id)){checkpoint();dragState={start:p,base:clone(design),ids:[...selectedIds],primary:hit.id,moved:false};$('cad-canvas').setPointerCapture(ev.pointerId)}});
$('cad-canvas').addEventListener('pointermove',ev=>{if(!dragState)return;const p=planPoint(ev),primary=dragState.base.elements.find(o=>o.id===dragState.primary);let dx=p.x-dragState.start.x,dy=p.y-dragState.start.y;if(snap){const others=dragState.base.elements.filter(o=>!dragState.ids.includes(o.id));const sp=snapGeometryPoint(primary.x+dx,primary.y+dy,others,.2,true,.22);dx=sp.x-primary.x;dy=sp.y-primary.y}if(Math.hypot(dx,dy)<.01)return;dragState.moved=true;design=clone(dragState.base);transformSelection(design,dragState.ids,dx,dy);for(const id of dragState.ids)constrainHostedOpening(design,id);renderCad();$('cad-status').textContent='Moving '+dragState.ids.length+' object(s) · '+dx.toFixed(2)+', '+dy.toFixed(2)+' m'});
$('cad-canvas').addEventListener('pointerup',ev=>{if(!dragState)return;const state=dragState;dragState=null;if(state.moved){const check=validateGeometry(design);if(!check.valid){design=state.base;$('cad-status').textContent='Move cancelled · '+check.errors.join(' · ');renderCad()}else{dirty('Moved '+state.ids.length+' object(s) · geometry validated');ignoreNextPlanClick=true}}});
$('cad-canvas').addEventListener('click',ev=>{const p=planPoint(ev);if(tool==='measure'){$('cad-status').textContent='X '+p.x.toFixed(2)+' m · Y '+p.y.toFixed(2)+' m';return}if(tool==='select'){if(ignoreNextPlanClick){ignoreNextPlanClick=false;return}return}addObject(p.x,p.y)});
$('cad-viewport').addEventListener('click',e=>{if(tool==='select'){const hit=viewport?.pick(e)||null;if(hit){selected=hit;if(e.shiftKey){if(selectedIds.has(hit))selectedIds.delete(hit);else selectedIds.add(hit)}else selectedIds=new Set([hit])}else if(!e.shiftKey){selected=null;selectedIds.clear()}renderCad()}});
$('snap-toggle').onclick=()=>{snap=!snap;$('snap-toggle').textContent='Snap: '+(snap?'ON':'OFF');$('snap-toggle').classList.toggle('active',snap)};
