$('undo').onclick=undo;$('redo').onclick=redo;
function selectedObjectIds(){return [...new Set(selectedIds.size?selectedIds:(selected?[selected]:[]))]}
function commitEdit(label,fn){const before=clone(design);const result=fn();if(!result?.ok){design=before;$('cad-status').textContent=result?.reason||'Operation could not be completed';return}const check=validateGeometry(design);if(!check.valid){design=before;$('cad-status').textContent='Edit rejected · '+check.errors.join(' · ');renderCad();return}checkpointFrom(before);dirty(label+' · '+(result.changed??1)+' object(s) · validated')}
function checkpointFrom(before){history.push(before);if(history.length>60)history.shift();future=[]}
$('rotate-left').onclick=()=>commitEdit('Rotate −15°',()=>(()=>{const r=rotateSelection(design,selectedObjectIds(),-15);for(const id of selectedObjectIds())constrainHostedOpening(design,id);return r})());
$('rotate-right').onclick=()=>commitEdit('Rotate +15°',()=>(()=>{const r=rotateSelection(design,selectedObjectIds(),15);for(const id of selectedObjectIds())constrainHostedOpening(design,id);return r})());
$('resize-length-up').onclick=()=>commitEdit('Increase length 10%',()=>{const ids=selectedObjectIds();if(ids.length!==1)return{ok:false,reason:'Resize one object at a time'};return resizeElement(design,ids[0],'length',1.1)});
$('resize-length-down').onclick=()=>commitEdit('Reduce length 10%',()=>{const ids=selectedObjectIds();if(ids.length!==1)return{ok:false,reason:'Resize one object at a time'};return resizeElement(design,ids[0],'length',.9)});
