$('resize-width-down').onclick=()=>commitEdit('Reduce width 10%',()=>{const ids=selectedObjectIds();if(ids.length!==1)return{ok:false,reason:'Resize one object at a time'};return resizeElement(design,ids[0],'width',.9)});
$('resize-height-up').onclick=()=>commitEdit('Increase height 10%',()=>{const ids=selectedObjectIds();if(ids.length!==1)return{ok:false,reason:'Resize one object at a time'};return resizeElement(design,ids[0],'height',1.1)});
$('resize-height-down').onclick=()=>commitEdit('Reduce height 10%',()=>{const ids=selectedObjectIds();if(ids.length!==1)return{ok:false,reason:'Resize one object at a time'};return resizeElement(design,ids[0],'height',.9)});
$('align-x').onclick=()=>commitEdit('Align centres on X',()=>alignSelection(design,selectedObjectIds(),'x','center'));
$('align-y').onclick=()=>commitEdit('Align centres on Y',()=>alignSelection(design,selectedObjectIds(),'y','center'));
$('offset').onclick=()=>{const ids=selectedObjectIds();if(ids.length!==1){$('cad-status').textContent='Select one object to offset';return}const d=Number(prompt('Parallel offset distance in metres','0.20'));if(!Number.isFinite(d)||d===0)return;commitEdit('Parallel offset '+d.toFixed(2)+' m',()=>offsetElement(design,ids[0],Math.abs(d),Math.sign(d)))};
