async function fieldRecords(type){return window.desktop.listRecords?window.desktop.listRecords(type):[]}
async function saveField(type,payload,id){return window.desktop.saveRecord({entityType:type,id,projectId:payload.projectId||null,payload})}
function populateFieldSelects(){const chat=$('team-chat-group');if(chat){const selected=chat.value;for(const p of projects){const id='project-'+p.id;if(![...chat.options].some(o=>o.value===id))chat.add(new Option(p.title+' · project team',id))}chat.value=selected||'company-general'}for(const id of ['report-project','whatsapp-project']){const s=$(id);if(!s)return;const v=s.value;s.replaceChildren(new Option('Select project',''));for(const p of projects)s.add(new Option(p.title,p.id));s.value=v}for(const id of ['report-staff','whatsapp-staff']){const s=$(id);if(!s)return;const v=s.value;s.replaceChildren(new Option('Select registered staff',''));for(const p of fieldStaff.filter(x=>x.active!==false))s.add(new Option(p.name+' · '+p.position,p.id));s.value=v||currentStaffId}}
function renderStaff(){const root=$('staff-directory');$('staff-count').textContent=fieldStaff.length+' people';const active=fieldStaff.find(s=>s.id===currentStaffId);$('active-staff-badge').textContent=active?active.name+' · '+active.position:'No staff profile selected';if(!fieldStaff.length){root.className='field-list empty';root.textContent='No staff registered yet.';populateFieldSelects();return}root.className='field-list';root.replaceChildren();for(const s of fieldStaff){const row=document.createElement('div');row.className='field-row';const info=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');b.textContent=s.name+' · '+s.position;small.textContent=s.role+' · '+s.employmentType+' · '+(s.trade||'General')+' · '+(s.active?'Active':'Inactive');info.append(b,small);const use=document.createElement('button');use.className='quiet';use.textContent=s.id===currentStaffId?'Current profile':'Use profile';use.onclick=()=>{currentStaffId=s.id;localStorage.setItem('conflow-current-staff',s.id);$('staff-name').value=s.name;$('staff-position').value=s.position;$('staff-role').value=s.role;$('staff-employment').value=s.employmentType;$('staff-phone').value=s.phone||'';$('staff-trade').value=s.trade||'';$('staff-active').checked=s.active!==false;$('staff-privacy-consent').checked=s.privacyAcknowledged===true;populateFieldSelects();renderStaff()};row.append(info,use);root.append(row)}populateFieldSelects()}
function renderSiteReports(){const root=$('site-report-feed');$('report-count').textContent=siteReports.length+' reports';if(!siteReports.length){root.className='field-list empty';root.textContent='No site reports submitted yet.';return}root.className='field-list';root.replaceChildren();for(const r of siteReports){const row=document.createElement('article');row.className='field-row report-card';const info=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small'),p=document.createElement('p');b.textContent=(projects.find(x=>x.id===r.projectId)?.title||'Project')+' · '+r.activity;small.textContent=(r.staffName||'Staff')+' · '+new Date(r.createdAt).toLocaleString()+' · '+r.progressPercent+'% progress · '+(r.status||'Submitted');p.textContent=r.summary+(r.issues?' | Issues: '+r.issues:'')+(r.actionRequired?' | Action: '+r.actionRequired:'');info.append(b,small,p);row.append(info);root.append(row)}}
function renderTeamMessages(){const root=$('team-chat-messages'),group=$('team-chat-group').value,rows=teamMessages.filter(m=>m.groupId===group).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));root.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='No messages in this group yet.';root.append(p);return}for(const m of rows){const item=document.createElement('div');item.className='chat-message';const who=document.createElement('b'),body=document.createElement('p'),time=document.createElement('small');who.textContent=m.senderName+' · '+m.senderPosition;body.textContent=m.text;time.textContent=new Date(m.createdAt).toLocaleString()+' · '+(m.syncState==='synced'?'Synced':'Pending company sync');item.append(who,body,time);root.append(item)}root.scrollTop=root.scrollHeight}
function renderWhatsAppReviews(){const root=$('whatsapp-review-list');root.replaceChildren();if(!whatsappReviews.length){root.textContent='No WhatsApp exports submitted for review.';return}for(const x of whatsappReviews){const row=document.createElement('div');row.className='field-row';const b=document.createElement('b'),small=document.createElement('small');b.textContent=x.fileName+' · '+(projects.find(p=>p.id===x.projectId)?.title||'Project');small.textContent=(x.staffName||'Staff')+' · '+x.messageCount+' detected message lines · Pending company review';row.append(b,small);root.append(row)}}
async function loadFieldOperations(){[fieldStaff,siteReports,teamMessages,whatsappReviews]=await Promise.all(['staff','site_report','team_message','whatsapp_review'].map(fieldRecords));fieldStaff=fieldStaff.map(x=>({...x,...x.payload,id:x.id}));siteReports=siteReports.map(x=>({...x.payload,id:x.id,syncState:x.syncState}));teamMessages=teamMessages.map(x=>({...x.payload,id:x.id,syncState:x.syncState}));whatsappReviews=whatsappReviews.map(x=>({...x.payload,id:x.id}));renderStaff();renderSiteReports();renderTeamMessages();renderWhatsAppReviews()}
$('staff-form').onsubmit=async e=>{e.preventDefault();try{const record=validateStaff({id:currentStaffId||undefined,name:$('staff-name').value,position:$('staff-position').value,role:$('staff-role').value,employmentType:$('staff-employment').value,phone:$('staff-phone').value,trade:$('staff-trade').value,active:$('staff-active').checked,privacyAcknowledged:$('staff-privacy-consent').checked});const saved=await saveField('staff',record,record.id);currentStaffId=saved.id;localStorage.setItem('conflow-current-staff',saved.id);await loadFieldOperations();$('cad-status').textContent='Staff profile saved locally and queued for company sync'}catch(err){alert(err.message)}};
$('site-report-form').onsubmit=async e=>{e.preventDefault();try{const staff=fieldStaff.find(s=>s.id===$('report-staff').value);const projectId=$('report-project').value;const files=[...$('report-files').files];if(files.length>5)throw new Error('Attach no more than 5 files per report');if(files.reduce((n,x)=>n+x.size,0)>8*1024*1024)throw new Error('Total report attachments must not exceed 8 MB');const attachments=[];for(const file of files){if(file.size>2*1024*1024)throw new Error(file.name+' exceeds the 2 MB per-file limit');attachments.push({name:file.name,type:file.type,size:file.size,dataUrl:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})})}const report=validateSiteReport({projectId,staffId:staff?.id,staffName:staff?.name,staffPosition:staff?.position,location:$('report-location').value,activity:$('report-activity').value,progressPercent:$('report-progress').value,summary:$('report-summary').value,issues:$('report-issues').value,actionRequired:$('report-action').value,attachments});const saved=await saveField('site_report',report);siteReports.unshift({...report,id:saved.id});renderSiteReports();e.target.reset();$('report-progress').value=0;$('cad-status').textContent='Site report saved locally and queued for company review';await refresh()}catch(err){alert(err.message)}};
$('team-chat-group').onchange=renderTeamMessages;
$('team-chat-form').onsubmit=async e=>{e.preventDefault();const staff=fieldStaff.find(s=>s.id===currentStaffId);if(!staff){alert('Register or select your staff profile before sending a group message.');return}const textValue=$('team-chat-input').value.trim();if(!textValue)return;const msg={groupId:$('team-chat-group').value,senderId:staff.id,senderName:staff.name,senderPosition:staff.position,text:textValue,createdAt:new Date().toISOString(),syncState:'pending'};const saved=await saveField('team_message',msg);teamMessages.push({...msg,id:saved.id});$('team-chat-input').value='';renderTeamMessages();await refresh()};
$('whatsapp-form').onsubmit=async e=>{e.preventDefault();try{const staff=fieldStaff.find(s=>s.id===$('whatsapp-staff').value),projectId=$('whatsapp-project').value,file=$('whatsapp-file').files[0];if(!file)throw new Error('Choose a WhatsApp text export');if(file.size>2*1024*1024)throw new Error('WhatsApp text export exceeds 2 MB');const textValue=await file.text(),parsed=parseWhatsAppExport(textValue);if(!canSubmitWhatsAppReview({consent:$('whatsapp-consent').checked,staffId:staff?.id,projectId}))throw new Error('Select a staff member and project and confirm permission to share this export');const item={projectId,staffId:staff.id,staffName:staff.name,fileName:file.name,...parsed,reviewStatus:'PENDING_COMPANY_REVIEW',consentConfirmed:true};const saved=await saveField('whatsapp_review',item);whatsappReviews.unshift({...item,id:saved.id});renderWhatsAppReviews();e.target.reset();$('cad-status').textContent='Selected WhatsApp work export uploaded to local company review queue';await refresh()}catch(err){alert(err.message)}};
$('report-share-whatsapp').onclick=()=>{const project=projects.find(p=>p.id===$('report-project').value)?.title||'Project';const staff=fieldStaff.find(s=>s.id===$('report-staff').value);const textValue='BuildFlow 1 site update | '+project+' | '+(staff?.name||'Staff')+' | '+$('report-activity').value+' | '+$('report-progress').value+'% progress | '+$('report-summary').value;window.open('https://wa.me/?text='+encodeURIComponent(textValue),'_blank','noopener')};

