   const index=items.indexOf(item),tr=document.createElement('tr');serial++;
   makeCell(tr,'td',String(serial));
   const desc=makeCell(tr,'td'),di=document.createElement('input');di.value=item.description||'';di.setAttribute('aria-label','Item description');di.onchange=()=>item.description=di.value;desc.append(di);
   const spec=document.createElement('input');spec.value=item.specification||'';spec.placeholder='Workmanship / material specification';spec.setAttribute('aria-label','Item specification');spec.onchange=()=>item.specification=spec.value;desc.append(spec);
   const dr=document.createElement('input');dr.value=item.drawingReference||'';dr.placeholder='Drawing ref.';dr.setAttribute('aria-label','Drawing reference');dr.onchange=()=>item.drawingReference=dr.value;desc.append(dr);
   const small=document.createElement('small');small.className='source-ref';small.title=item.measurementBasis||'';small.textContent=(item.sourceId?'CAD · '+(design.elements.find(e=>e.id===item.sourceId)?.type||'object')+' · ':'Manual · ')+(item.measureCode||'unclassified')+' · '+(item.verificationStatus||'Pending QS verification');desc.append(small);
   const unit=makeCell(tr,'td'),ui=document.createElement('input');ui.value=item.unit||'Item';ui.setAttribute('aria-label','Unit');ui.onchange=()=>item.unit=ui.value;unit.append(ui);
   const qty=makeCell(tr,'td'),qi=document.createElement('input');qi.type='number';qi.min='0';qi.step='.001';qi.value=Number(item.quantity||0).toFixed(3);qi.setAttribute('aria-label','Quantity');qi.onchange=()=>{item.quantity=Math.max(0,+qi.value||0);item.quantityOverride=true;renderBoq()};qty.append(qi);
   const waste=makeCell(tr,'td'),wi=document.createElement('input');wi.type='number';wi.min='0';wi.max='100';wi.step='.1';wi.value=Number(item.waste||0);wi.setAttribute('aria-label','Material waste percentage');wi.onchange=()=>{item.waste=Math.max(0,+wi.value||0);item.rateOverride=null;renderBoq()};waste.append(wi);
